async function seedPopularTreatments(): Promise<{ groupsCreated: number; treatmentsCreated: number }> {
  let groupsCreated = 0;
  let treatmentsCreated = 0;
  for (const [groupIdx, group] of POPULAR_TREATMENT_SEED.entries()) {
    let groupRow = await prisma.popularTreatmentGroup.findUnique({ where: { slug: group.slug } });
    if (!groupRow) {
      groupRow = await prisma.popularTreatmentGroup.create({
        data: { name: group.name, slug: group.slug, sortOrder: groupIdx },
      });
      groupsCreated++;
    }
    for (const [treatmentIdx, treatment] of group.treatments.entries()) {
      const existing = await prisma.popularTreatment.findUnique({ where: { slug: treatment.slug } });
      if (existing) continue;
      await prisma.popularTreatment.create({
        data: { name: treatment.name, slug: treatment.slug, groupId: groupRow.id, sortOrder: treatmentIdx },
      });
      treatmentsCreated++;
    }
  }
  return { groupsCreated, treatmentsCreated };
}

async function seedCategoryTaxonomy(): Promise<Map<string, string>> {
  const categoryIdBySlug = new Map<string, string>();

  for (const top of CATEGORY_TAXONOMY) {
    const topRow = await prisma.category.upsert({
      where: { slug: top.slug },
      update: { isActive: true },
      create: { name: top.name, slug: top.slug, type: top.type },
    });
    categoryIdBySlug.set(top.slug, topRow.id);

    for (const [subIdx, sub] of top.children.entries()) {
      const subRow = await prisma.category.upsert({
        where: { slug: sub.slug },
        update: { isActive: true },
        create: { name: sub.name, slug: sub.slug, parentId: topRow.id, sortOrder: subIdx },
      });
      categoryIdBySlug.set(sub.slug, subRow.id);

      for (const [leafIdx, leaf] of (sub.children ?? []).entries()) {
        const leafRow = await prisma.category.upsert({
          where: { slug: leaf.slug },
          update: { isActive: true },
          create: { name: leaf.name, slug: leaf.slug, parentId: subRow.id, sortOrder: leafIdx },
        });
        categoryIdBySlug.set(leaf.slug, leafRow.id);
      }
    }
  }

  return categoryIdBySlug;
}

/** lowercase, non-alphanumeric runs -> single '-', leading/trailing '-' trimmed. */
/**
 * One-off backfill for `Vendor.slug` (added in the Therapist/storefront migration) — every
 * existing Vendor row (the 3 demo vendors, and any other pre-existing row) predates this column,
 * so this walks every Vendor with `slug: null` and assigns one derived from `businessName` (or
 * the row's own `id` if businessName is unset). Idempotent and safe to re-run: only ever touches
 * rows that still have `slug: null`. Shares `ensureUniqueSlug` with `vendor.service.ts`'s
 * `createVendor`/`createSelfVendor`/`updateVendor` — this used to be a local copy of the same
 * fallback logic; now there's one implementation.
 */
async function backfillVendorSlugs(): Promise<number> {
  const vendorsMissingSlug = await prisma.vendor.findMany({ where: { slug: null } });
  for (const v of vendorsMissingSlug) {
    const slug = await ensureUniqueSlug(v.businessName ?? v.id, v.id, (candidate) =>
      prisma.vendor.findUnique({ where: { slug: candidate } }).then(Boolean),
    );
    await prisma.vendor.update({ where: { id: v.id }, data: { slug } });
  }
  return vendorsMissingSlug.length;
}

/** Same demo hours every weekday, a shorter Saturday, closed Sunday — good enough for local dev. */
const DEMO_OPENING_HOURS = {
  mon: '09:00-20:00',
  tue: '09:00-20:00',
  wed: '09:00-20:00',
  thu: '09:00-20:00',
  fri: '09:00-20:00',
  sat: '10:00-18:00',
  sun: 'closed',
};

/** One-off backfill for `Branch.openingHours` (same migration as Vendor.slug) — every existing
 *  Branch row predates this column. Fetches the (small, demo-sized) branch list and filters in
 *  application code rather than a Prisma Json-null `where` clause (Json columns need
 *  `Prisma.DbNull`/`Prisma.JsonNull`, not a bare `null`, and this dataset is small enough that
 *  the extra round-trip cost is irrelevant). Idempotent and safe to re-run. */
async function backfillBranchOpeningHours(): Promise<number> {
  const branches = await prisma.branch.findMany();
  const missing = branches.filter((b) => b.openingHours === null);
  for (const b of missing) {
    await prisma.branch.update({ where: { id: b.id }, data: { openingHours: DEMO_OPENING_HOURS as Prisma.InputJsonValue } });
  }
  return missing.length;
}

// ─── Demo marketplace dataset ────────────────────────────────────────────────
// Category → Sub-category → Product → Deal/Therapist → Vendor → Branch → Cart →
// Checkout → Order → Payment, all as real rows the real APIs already serve — no mock data, no
// parallel demo system, and no separate Booking flow (Deal/Product/Therapist all become
// OrderItems directly). Every function below is safe to re-run: upsert on the model's real
// unique key where one exists (User.phone, Category/Product/Deal.slug, Cart.customerId,
// DealPackage's (dealId,durationMinutes), TherapistPackage's (therapistId,durationMinutes),
// Payment.providerOrderId), or a findFirst-then-create-if-missing guard where it doesn't (Branch,
// Therapist, CartItem, Order). Never `deleteMany` against any of these tables — this only ever
// layers demo rows on top of whatever's already there.

