async function seedTherapists(
  vendorIdByKey: Map<string, string>,
  branchIdByKey: Map<string, string>,
  categoryIdBySlug: Map<string, string>,
): Promise<number> {
  const vendorKeyByBranchKey = new Map<string, string>();
  for (const v of VENDOR_SEEDS) {
    for (const b of v.branches) vendorKeyByBranchKey.set(b.key, v.key);
  }

  let created = 0;
  for (const t of THERAPIST_SEEDS) {
    const branchId = branchIdByKey.get(t.branchKey)!;
    const vendorId = vendorIdByKey.get(vendorKeyByBranchKey.get(t.branchKey)!)!;

    const photoUrl = staticCategoryImage(t.specializationCategorySlug ?? 'wellness');
    const existing = await prisma.therapist.findFirst({ where: { branchId, personName: t.name } });
    if (!existing) {
      await prisma.therapist.create({
        data: {
          vendorId,
          branchId,
          personName: t.name,
          specialization: t.specialization,
          specializationCategoryId: t.specializationCategorySlug ? categoryIdBySlug.get(t.specializationCategorySlug) : undefined,
          bio: t.bio,
          experienceYears: t.experienceYears,
          photoUrl,
          isActive: true,
        },
      });
      created++;
    } else {
      // Refresh only the demo photo so existing therapist profile data stays untouched.
      await prisma.therapist.update({ where: { id: existing.id }, data: { photoUrl } });
    }
  }
  return created;
}

const DEMO_CUSTOMER_PHONE = '+919810099999';
const DEMO_CUSTOMER_EMAIL = 'demo.customer@seed.msd.local';

async function seedDemoCustomer(roles: Map<string, { id: string; isSuperAdmin: boolean }>): Promise<string> {
  const customerRole = roles.get('customer');
  const user = await prisma.user.upsert({
    where: { phone: DEMO_CUSTOMER_PHONE },
    update: { name: 'Demo Customer', email: DEMO_CUSTOMER_EMAIL },
    create: { name: 'Demo Customer', phone: DEMO_CUSTOMER_PHONE, email: DEMO_CUSTOMER_EMAIL },
  });
  if (customerRole) {
    await prisma.userRole.upsert({
      where: { userId_roleId: { userId: user.id, roleId: customerRole.id } },
      update: {},
      create: { userId: user.id, roleId: customerRole.id },
    });
  }
  return user.id;
}

const PACKAGE_DURATIONS = [30, 60, 90] as const;
const PACKAGE_MULTIPLIERS = [1, 1.6, 2.2] as const;

/** Every SERVICE deal gets a real 30/60/90-minute package menu — the unified Cart/Order flow
 *  requires selecting a package before a service Deal can be added to cart (see CartItem's own
 *  schema doc comment), so demo data needs real packages to exercise that flow. Priced as a
 *  multiple of the deal's own base price, rounded to a clean ten. Idempotent via DealPackage's
 *  own `@@unique([dealId, durationMinutes])` upsert key. */
async function seedDealPackages(): Promise<number> {
  const serviceDeals = await prisma.deal.findMany({ select: { id: true, salePrice: true, originalPrice: true } });
  let created = 0;
  for (const deal of serviceDeals) {
    const base = deal.salePrice.toNumber();
    const baseOriginal = deal.originalPrice ? deal.originalPrice.toNumber() : null;
    for (const [i, durationMinutes] of PACKAGE_DURATIONS.entries()) {
      const existing = await prisma.dealPackage.findUnique({ where: { dealId_durationMinutes: { dealId: deal.id, durationMinutes } } });
      if (existing) continue;
      const multiplier = PACKAGE_MULTIPLIERS[i];
      await prisma.dealPackage.create({
        data: {
          dealId: deal.id,
          durationMinutes,
          sellingPrice: Math.round((base * multiplier) / 10) * 10,
          originalPrice: baseOriginal ? Math.round((baseOriginal * multiplier) / 10) * 10 : null,
          sortOrder: i,
        },
      });
      created++;
    }
  }
  return created;
}

/** Every Therapist gets a real 30/60/90-minute package menu, entirely independent of any Deal
 *  (see TherapistPackage's own schema doc comment) — same "must have a package to be added to
 *  cart" requirement as seedDealPackages above. Idempotent via TherapistPackage's own
 *  `@@unique([therapistId, durationMinutes])` upsert key. */
async function seedTherapistPackages(): Promise<number> {
  const therapists = await prisma.therapist.findMany({ select: { id: true } });
  const basePriceByDuration = [1099, 1499, 1899];
  let created = 0;
  for (const t of therapists) {
    for (const [i, durationMinutes] of PACKAGE_DURATIONS.entries()) {
      const existing = await prisma.therapistPackage.findUnique({ where: { therapistId_durationMinutes: { therapistId: t.id, durationMinutes } } });
      if (existing) continue;
      await prisma.therapistPackage.create({
        data: { therapistId: t.id, durationMinutes, sellingPrice: basePriceByDuration[i], sortOrder: i },
      });
      created++;
    }
  }
  return created;
}

/** Multi-vendor, multi-kind cart, deliberately: two Product lines from Glow Beauty Studio plus
 *  one from Urban Wellness Spa, one Service-Deal line (Swedish Massage, with a package), and one
 *  Therapist line (Ramesh Kumar, with a package) — demonstrating (and exercising, on every seed
 *  run) the real unified Deal/Product/Therapist cart, all headed to ONE checkout/ONE Order (see
 *  CartItem's own schema doc comment; there is no separate Booking flow). A cart has no vendor/
 *  branch of its own — each item's own deal/therapist relation is authoritative. Idempotent via
 *  an explicit `findFirst` match on the exact line shape, same discipline as
 *  cart.service.ts#addItem (the compound unique index can't serve as an upsert key here since
 *  Postgres treats NULLs as pairwise-distinct). */
async function seedCart(customerId:string,dealIdBySlug:Map<string,string>,productIdBySlug:Map<string,string>):Promise<void>{
  const cart=await prisma.cart.upsert({where:{customerId},update:{},create:{customerId}});
  const upsertLine=async(line:{dealId?:string;dealPackageId?:string;therapistId?:string;therapistPackageId?:string;productId?:string;quantity:number;unitPrice:number})=>{
    const where={cartId:cart.id,dealId:line.dealId??null,dealPackageId:line.dealPackageId??null,therapistId:line.therapistId??null,therapistPackageId:line.therapistPackageId??null,productId:line.productId??null};
    const existing=await prisma.cartItem.findFirst({where});
    if(existing) await prisma.cartItem.update({where:{id:existing.id},data:{quantity:line.quantity,unitPrice:line.unitPrice}});
    else await prisma.cartItem.create({data:{...where,quantity:line.quantity,unitPrice:line.unitPrice}});
  };
  for(const item of [
    {productSlug:'hydrating-hair-shampoo-elite-delhi-cp',quantity:2},
    {productSlug:'vitamin-c-glow-serum-elite-delhi-cp',quantity:1},
    {productSlug:'spa-recovery-kit-serenity-delhi',quantity:1},
  ]){
    const productId=productIdBySlug.get(item.productSlug)!;
    const product=await prisma.product.findUniqueOrThrow({where:{id:productId}});
    await upsertLine({productId,quantity:item.quantity,unitPrice:product.price.toNumber()});
  }
  const massageDealId=dealIdBySlug.get('deep-tissue-recovery-urban-delhi')!;
  const massagePackage=await prisma.dealPackage.findFirstOrThrow({where:{dealId:massageDealId,durationMinutes:60}});
  await upsertLine({dealId:massageDealId,dealPackageId:massagePackage.id,quantity:1,unitPrice:massagePackage.sellingPrice.toNumber()});
  const therapist=await prisma.therapist.findFirstOrThrow({where:{personName:'Aditya Verma'}});
  const therapistPackage=await prisma.therapistPackage.findFirstOrThrow({where:{therapistId:therapist.id,durationMinutes:30}});
  await upsertLine({therapistId:therapist.id,therapistPackageId:therapistPackage.id,quantity:1,unitPrice:therapistPackage.sellingPrice.toNumber()});
}

async function seedWishlist(customerId:string,dealIdBySlug:Map<string,string>):Promise<void>{
  for(const slug of ['premium-glow-facial-glow-delhi','head-neck-relaxation-urban-delhi']){
    const dealId=dealIdBySlug.get(slug)!;
    await prisma.wishlistItem.upsert({where:{customerId_dealId:{customerId,dealId}},update:{},create:{customerId,dealId}});
  }
}

interface OrderLineInput {
  itemName: string;
  itemType: 'PRODUCT' | 'SERVICE';
  unitPrice: number;
  quantity: number;
  durationMinutes?: number;
  dealId?: string;
  dealPackageId?: string;
  therapistId?: string;
  therapistPackageId?: string;
  productId?: string;
  vendorId: string;
  /** Absent for a Product line — Product has no branch (see its own schema doc comment). */
  branchId?: string;
  vendorNameSnapshot: string;
  branchNameSnapshot?: string;
}

/**
 * A Deal(service)/Therapist/Product order created directly from real selections — mirrors what
 * order.service.ts#createOrderFromCart now produces at checkout for exactly this reason (there
 * is no Booking model anymore; every purchase kind becomes an OrderItem directly). Order.type is
 * PRODUCT only if every item is a Product line, else SERVICE — same rule as
 * order.service.ts#createOrderFromCart — so a Deal+Product+Therapist order here is a genuine
 * "Mixed" order by `describeOrderComposition`'s reading of its items, exactly like a real
 * checkout would produce. Idempotent the same way as seedProductOrder — findFirst-by-(customerId,
 * primary vendorId, primary branchId, type) then create-if-missing, so each demo order below uses
 * its own distinct vendor+branch combo.
 */
async function seedOrder(
  customerId: string,
  primaryVendorId: string,
  primaryBranchId: string | undefined,
  primaryVendorNameSnapshot: string,
  primaryBranchNameSnapshot: string | undefined,
  status: 'PENDING_PAYMENT' | 'CONFIRMED' | 'COMPLETED' | 'CANCELLED',
  items: OrderLineInput[],
): Promise<string> {
  const type = items.every((it) => it.itemType === 'PRODUCT') ? 'PRODUCT' : 'SERVICE';
  const existing = await prisma.order.findFirst({ where: { customerId, vendorId: primaryVendorId, branchId: primaryBranchId ?? null, type } });
  if (existing) return existing.id;

  let subtotal = 0;
  const itemsData = items.map((it) => {
    const lineTotal = it.unitPrice * it.quantity;
    subtotal += lineTotal;
    return {
      dealId: it.dealId ?? null,
      dealPackageId: it.dealPackageId ?? null,
      therapistId: it.therapistId ?? null,
      therapistPackageId: it.therapistPackageId ?? null,
      productId: it.productId ?? null,
      vendorId: it.vendorId,
      branchId: it.branchId ?? null,
      vendorNameSnapshot: it.vendorNameSnapshot,
      branchNameSnapshot: it.branchNameSnapshot ?? null,
      itemName: it.itemName,
      itemType: it.itemType,
      unitPrice: it.unitPrice,
      quantity: it.quantity,
      lineTotal,
      durationMinutes: it.durationMinutes ?? null,
    };
  });

  const order = await prisma.order.create({
    data: {
      customerId,
      vendorId: primaryVendorId,
      branchId: primaryBranchId ?? null,
      type,
      status,
      vendorNameSnapshot: primaryVendorNameSnapshot,
      branchNameSnapshot: primaryBranchNameSnapshot ?? null,
      subtotal,
      total: subtotal,
      items: { create: itemsData },
    } as unknown as Prisma.OrderUncheckedCreateInput,
  });

  return order.id;
}

interface ProductOrderItemInput {
  productId: string;
  itemName: string;
  unitPrice: number;
  quantity: number;
}

/** A PRODUCT order has no branch (Product has no branchId, see its own schema doc comment) and
 *  no other natural unique key — idempotency is findFirst-by-(customerId,vendorId,type,status)
 *  then create-if-missing (each demo PRODUCT order below uses its own distinct status so they
 *  never collide with each other on a re-run, even when they share a vendor). */
async function seedProductOrder(
  customerId: string,
  vendorId: string,
  vendorNameSnapshot: string,
  status: 'PENDING_PAYMENT' | 'CONFIRMED' | 'COMPLETED' | 'CANCELLED',
  items: ProductOrderItemInput[],
  cancellationReason?: string,
): Promise<string> {
  const existing = await prisma.order.findFirst({ where: { customerId, vendorId, branchId: null, type: 'PRODUCT', status } });
  if (existing) return existing.id;

  let subtotal = 0;
  const itemsData = items.map((it) => {
    const lineTotal = it.unitPrice * it.quantity;
    subtotal += lineTotal;
    return {
      productId: it.productId,
      vendorId,
      vendorNameSnapshot,
      itemName: it.itemName,
      itemType: 'PRODUCT' as const,
      unitPrice: it.unitPrice,
      quantity: it.quantity,
      lineTotal,
    };
  });

  const order = await prisma.order.create({
    data: {
      customerId,
      vendorId,
      type: 'PRODUCT',
      status,
      vendorNameSnapshot,
      subtotal,
      total: subtotal,
      cancellationReason: cancellationReason ?? null,
      items: { create: itemsData },
    } as unknown as Prisma.OrderUncheckedCreateInput,
  });

  return order.id;
}

/**
 * Fake, clearly-demo, deterministic Razorpay-shaped ids — `demo_`-prefixed so they can never
 * collide with or be mistaken for a real Razorpay order/payment id. Never calls Razorpay.
 *
 * Idempotent via findFirst-then-create/update-if-missing (NOT `upsert`) — unlike this file's
 * other upserts, `Payment.providerOrderId` is deliberately not `@unique` (a combined multi-order
 * checkout batch shares one Razorpay order across several Payment rows — see Payment's own
 * schema doc comment), so there is no unique key `upsert`'s `where` could use here.
 */
async function seedPayment(orderId: string, status: 'CREATED' | 'PAID', amount: number): Promise<void> {
  const providerOrderId = `demo_order_${orderId.slice(0, 18)}`;
  const providerPaymentId = status === 'PAID' ? `demo_pay_${orderId.slice(0, 18)}` : null;
  const data = {
    status,
    amount,
    providerPaymentId,
    signatureVerified: status === 'PAID',
  };
  const existing = await prisma.payment.findFirst({ where: { orderId, providerOrderId } });
  if (existing) {
    await prisma.payment.update({ where: { id: existing.id }, data });
  } else {
    await prisma.payment.create({
      data: {
        orderId,
        provider: 'RAZORPAY',
        providerOrderId,
        currency: 'INR',
        ...data,
      },
    });
  }
}

/**
 * Ties the demo customer's Cart/Orders/Payments together — every purchase kind (Deal, Product,
 * Therapist) is an OrderItem directly, no Booking involved:
 *  1. MIXED order (COMPLETED, Glow/Golghar: Haircut Deal + Hair Shampoo Product + Anjali Mehta
 *     Therapist, all in ONE order) with a PAID payment — the canonical "one checkout, one Order,
 *     several kinds of item" example.
 *  2. THERAPIST order (CONFIRMED, Urban/Civil Lines: Ramesh Kumar) with a PAID payment.
 *  3. DEAL order (CONFIRMED, Urban/Medical College Road: Deep Tissue Massage) with a PAID payment.
 *  4. PRODUCT order (CONFIRMED, Glow Beauty Studio) with a PAID payment.
 *  5. PRODUCT order (PENDING_PAYMENT, Urban Wellness Spa) with a CREATED (unpaid) payment.
 *  6. PRODUCT order (CANCELLED, Glow Beauty Studio) with no payment.
 * Each order uses its own distinct vendor+type(+status, for a PRODUCT order — no branch to
 * disambiguate by, see `seedProductOrder`'s doc comment) combo — see `seedOrder`'s doc comment.
 */
async function seedDemoCustomerActivity(
  customerId:string,dealIdBySlug:Map<string,string>,productIdBySlug:Map<string,string>,
  vendorIdByKey:Map<string,string>,branchIdByKey:Map<string,string>,
):Promise<void>{
  await seedCart(customerId,dealIdBySlug,productIdBySlug);
  await seedWishlist(customerId,dealIdBySlug);

  const urbanId=vendorIdByKey.get('urban')!;
  const urbanBranchId=branchIdByKey.get('urban-delhi')!;
  const aditya=await prisma.therapist.findFirstOrThrow({where:{personName:'Aditya Verma'}});
  const adityaPackage=await prisma.therapistPackage.findFirstOrThrow({where:{therapistId:aditya.id,durationMinutes:60}});
  const massageDealId=dealIdBySlug.get('deep-tissue-recovery-urban-delhi')!;
  const massagePackage=await prisma.dealPackage.findFirstOrThrow({where:{dealId:massageDealId,durationMinutes:90}});
  const productId=productIdBySlug.get('hydrating-hair-shampoo-elite-delhi-cp')!;
  const product=await prisma.product.findUniqueOrThrow({where:{id:productId}});

  const mixedOrderId=await seedOrder(customerId,urbanId,urbanBranchId,'SereneAura Spa & Wellness','Saket Branch','COMPLETED',[
    {dealId:massageDealId,dealPackageId:massagePackage.id,itemName:'Deep Tissue Recovery Massage',itemType:'SERVICE',unitPrice:massagePackage.sellingPrice.toNumber(),quantity:1,durationMinutes:massagePackage.durationMinutes,vendorId:urbanId,branchId:urbanBranchId,vendorNameSnapshot:'SereneAura Spa & Wellness',branchNameSnapshot:'Saket Branch'},
    {therapistId:aditya.id,therapistPackageId:adityaPackage.id,itemName:`${aditya.specialization} — ${aditya.personName}`,itemType:'SERVICE',unitPrice:adityaPackage.sellingPrice.toNumber(),quantity:1,durationMinutes:adityaPackage.durationMinutes,vendorId:urbanId,branchId:urbanBranchId,vendorNameSnapshot:'SereneAura Spa & Wellness',branchNameSnapshot:'Saket Branch'},
    {productId,itemName:product.name,itemType:'PRODUCT',unitPrice:product.price.toNumber(),quantity:1,vendorId:vendorIdByKey.get('elite')!,vendorNameSnapshot:'UrbanGlow Beauty & Care'},
  ]);
  const mixedOrder=await prisma.order.findUniqueOrThrow({where:{id:mixedOrderId}});
  await seedPayment(mixedOrder.id,'PAID',mixedOrder.total.toNumber());

  const therapistOrderId=await seedOrder(customerId,urbanId,urbanBranchId,'SereneAura Spa & Wellness','Saket Branch','CONFIRMED',[
    {therapistId:aditya.id,therapistPackageId:adityaPackage.id,itemName:`${aditya.specialization} — ${aditya.personName}`,itemType:'SERVICE',unitPrice:adityaPackage.sellingPrice.toNumber(),quantity:1,durationMinutes:adityaPackage.durationMinutes,vendorId:urbanId,branchId:urbanBranchId,vendorNameSnapshot:'SereneAura Spa & Wellness',branchNameSnapshot:'Saket Branch'},
  ]);
  const therapistOrder=await prisma.order.findUniqueOrThrow({where:{id:therapistOrderId}});
  await seedPayment(therapistOrder.id,'PAID',therapistOrder.total.toNumber());

  const dealOrderId=await seedOrder(customerId,urbanId,urbanBranchId,'SereneAura Spa & Wellness','Saket Branch','PENDING_PAYMENT',[
    {dealId:massageDealId,dealPackageId:massagePackage.id,itemName:'Deep Tissue Recovery Massage',itemType:'SERVICE',unitPrice:massagePackage.sellingPrice.toNumber(),quantity:1,durationMinutes:massagePackage.durationMinutes,vendorId:urbanId,branchId:urbanBranchId,vendorNameSnapshot:'SereneAura Spa & Wellness',branchNameSnapshot:'Saket Branch'},
  ]);
  const dealOrder=await prisma.order.findUniqueOrThrow({where:{id:dealOrderId}});
  await seedPayment(dealOrder.id,'CREATED',dealOrder.total.toNumber());

  const productVendorId=vendorIdByKey.get('elite')!;
  const confirmedProductId=await seedProductOrder(customerId,productVendorId,'UrbanGlow Beauty & Care','CONFIRMED',[
    {productId,itemName:product.name,unitPrice:product.price.toNumber(),quantity:1},
    {productId:productIdBySlug.get('vitamin-c-glow-serum-elite-delhi-cp')!,itemName:'Vitamin C Glow Serum - Connaught Place',unitPrice:899,quantity:1},
  ]);
  const confirmedProduct=await prisma.order.findUniqueOrThrow({where:{id:confirmedProductId}});
  await seedPayment(confirmedProduct.id,'PAID',confirmedProduct.total.toNumber());
}

/** Marks the retired taxonomy rows inactive when they already exist in an older
 * database. The new CATEGORY_TAXONOMY no longer contains these rows, but seedCategoryTaxonomy()
 * intentionally never deletes admin-created/stale rows, so this explicit backfill prevents the
 * retired category from remaining visible after a rerun. */
async function deactivateRemovedTaxonomyRows():Promise<number>{
  const activeSlugs=new Set<string>();
  for(const top of CATEGORY_TAXONOMY){activeSlugs.add(top.slug); for(const sub of top.children)activeSlugs.add(sub.slug);}
  const existing=await prisma.category.findMany({select:{id:true,slug:true}});
  const retiredIds=existing.filter((row)=>!activeSlugs.has(row.slug)).map((row)=>row.id);
  if(!retiredIds.length)return 0;
  const result=await prisma.category.updateMany({where:{id:{in:retiredIds}},data:{isActive:false}});
  return result.count;
}

function validateDemoSeedDataset():void{
  if(VENDOR_SEEDS.length!==5)throw new Error('Seed validation failed: exactly 5 vendors are required.');
  const branchCount=VENDOR_SEEDS.reduce((n,v)=>n+v.branches.length,0);
  if(branchCount!==18)throw new Error(`Seed validation failed: expected 18 branches, got ${branchCount}.`);
  if(SERVICE_DEAL_SEEDS.length!==38)throw new Error('Seed validation failed: exactly 38 deals are required.');
  if(PRODUCT_SEEDS.length!==32)throw new Error('Seed validation failed: exactly 32 products are required.');
  if(THERAPIST_SEEDS.length!==34)throw new Error('Seed validation failed: exactly 34 therapists are required.');
  const taxonomySubcategories=CATEGORY_TAXONOMY.flatMap((top)=>top.children.map((sub)=>sub.slug));
  const seeded=new Set<string>();
  for(const x of SERVICE_DEAL_SEEDS)seeded.add(x.subcategorySlug);
  for(const x of PRODUCT_SEEDS)seeded.add(x.subcategorySlug);
  for(const x of THERAPIST_SEEDS)if(x.specializationCategorySlug)seeded.add(x.specializationCategorySlug);
  const missing=taxonomySubcategories.filter((slug)=>!seeded.has(slug));
  if(missing.length)throw new Error(`Seed validation failed: subcategories without data: ${missing.join(', ')}`);
  const branchKeys=new Set(VENDOR_SEEDS.flatMap((v)=>v.branches.map((b)=>b.key)));
  const count=(rows:any[])=>rows.reduce((m,row)=>(m.set(row.branchKey,(m.get(row.branchKey)??0)+1),m),new Map<string,number>());
  const dc=count(SERVICE_DEAL_SEEDS),pc=count(PRODUCT_SEEDS),tc=count(THERAPIST_SEEDS);
  for(const row of [...SERVICE_DEAL_SEEDS,...PRODUCT_SEEDS,...THERAPIST_SEEDS])if(!branchKeys.has(row.branchKey))throw new Error(`Seed validation failed: unknown branch ${row.branchKey}.`);
  for(const v of VENDOR_SEEDS)for(const b of v.branches){const d=dc.get(b.key)??0,p=pc.get(b.key)??0,t=tc.get(b.key)??0;
    if(v.key==='glow'&&d!==3)throw new Error('Vendor 1 must have exactly 3 deals.');
    if(v.key==='urban'&&(d!==3||t!==2))throw new Error('Vendor 2 must have exactly 3 deals and 2 therapists.');
    if(['elite','serenity','vitality'].includes(v.key)&&(d<2||p<2||t<2))throw new Error(`${v.key}/${b.key} must have at least 2 deals, 2 products and 2 therapists.`);
  }
}

async function main() {
  validateDemoSeedDataset();
  const roles = await seedRoles();
  const permissionIdByKey = await seedPermissions();
  // Every menuKey that used to be shared by multiple menu nodes and has since been split into
  // distinct per-node keys — add a new `{ oldMenuKey, newMenuKeys }` entry here whenever another
  // such split happens, so every role's (including custom roles') existing access is preserved.
  await migrateSharedKeySplitGrants(
    prisma,
    [{ oldMenuKey: 'cms.blog', newMenuKeys: ['cms.blog.pages', 'cms.blog.articles'] }],
    permissionIdByKey,
  );
  await grantAllPermissionsToSuperAdmins(roles, permissionIdByKey);
  await grantStarterPermissions(roles, permissionIdByKey);
  await seedDashboardWidgets(roles);
  await seedSuperAdminUser(roles);
  console.log(`Seeded ${roles.size} roles and ${permissionIdByKey.size} permissions.`);

  const categoryIdBySlug = await seedCategoryTaxonomy();
  const retiredTaxonomyRows = await deactivateRemovedTaxonomyRows();
  const { groupsCreated, treatmentsCreated } = await seedPopularTreatments();
  if (groupsCreated > 0 || treatmentsCreated > 0) {
    console.log(`Seeded ${groupsCreated} new popular treatment group(s) and ${treatmentsCreated} new treatment(s).`);
  }
  // Vendors must exist before Products (Product.vendorId is required — see the
  // direct_category_access migration), unlike the old shared-master-row model's ordering.
  const { vendorIdByKey, branchIdByKey } = await seedVendorsAndBranches(roles);
  const productIdBySlug = await seedProducts(categoryIdBySlug, vendorIdByKey);
  const dealIdBySlug = await seedDeals(categoryIdBySlug, vendorIdByKey, branchIdByKey);
  await seedVendorModulesAndCategoryAccess(vendorIdByKey, categoryIdBySlug);

  const backfilledSlugs = await backfillVendorSlugs();
  const backfilledHours = await backfillBranchOpeningHours();
  const therapistsCreated = await seedTherapists(vendorIdByKey, branchIdByKey, categoryIdBySlug);
  // Every SERVICE deal and every Therapist needs a real 30/60/90-min package before the demo
  // customer's cart/orders below (or the unified Add-to-Cart flow) can select one.
  const dealPackagesCreated = await seedDealPackages();
  const therapistPackagesCreated = await seedTherapistPackages();
  const demoCustomerId = await seedDemoCustomer(roles);
  await seedDemoCustomerActivity(demoCustomerId, dealIdBySlug, productIdBySlug, vendorIdByKey, branchIdByKey);

  const [
    categoryCount,
    subcategoryCount,
    productCount,
    vendorCount,
    branchCount,
    serviceDealCount,
    cartItemCount,
    wishlistItemCount,
    orderCount,
    paymentCount,
    therapistCount,
    vendorCategoryAccessCount,
  ] = await Promise.all([
    prisma.category.count(),
    prisma.category.count({ where: { parentId: { not: null } } }),
    prisma.product.count(),
    prisma.vendor.count(),
    prisma.branch.count(),
    prisma.deal.count(),
    prisma.cartItem.count({ where: { cart: { customerId: demoCustomerId } } }),
    prisma.wishlistItem.count({ where: { customerId: demoCustomerId } }),
    prisma.order.count({ where: { customerId: demoCustomerId } }),
    prisma.payment.count({ where: { order: { customerId: demoCustomerId } } }),
    prisma.therapist.count(),
    prisma.vendorCategoryAccess.count(),
  ]);

  console.log('\n── Demo marketplace dataset ──────────────────────────────');
  console.log(`Categories:      ${categoryCount} (${subcategoryCount} sub-categories)`);
  console.log(`Retired taxonomy rows deactivated: ${retiredTaxonomyRows}`);
  console.log(`Products:        ${productCount}`);
  console.log(`Vendor category grants: ${vendorCategoryAccessCount}`);
  console.log(`Vendors:         ${vendorCount} (${VENDOR_SEEDS.length} vendor owner users, ${backfilledSlugs} slug(s) backfilled)`);
  console.log(`Branches:        ${branchCount} (${backfilledHours} openingHours backfilled)`);
  console.log(`Deals:           ${serviceDealCount} (${dealPackagesCreated} packages created this run)`);
  console.log(`Therapists:      ${therapistCount} (${therapistsCreated} created this run, ${therapistPackagesCreated} packages created this run)`);
  console.log(`Cart items:      ${cartItemCount} (demo customer)`);
  console.log(`Wishlist items:  ${wishlistItemCount} (demo customer)`);
  console.log(`Orders:          ${orderCount} (demo customer)`);
  console.log(`Payments:        ${paymentCount} (demo customer's orders)`);
  console.log(`\nDemo customer login: phone ${DEMO_CUSTOMER_PHONE} / email ${DEMO_CUSTOMER_EMAIL}`);
  console.log('Demo vendor owners:');
  for (const v of VENDOR_SEEDS) {
    console.log(`  - ${v.businessName}: phone ${v.ownerPhone} / email ${v.ownerEmail}`);
  }
  console.log('Sign in via OTP (POST /auth/otp/send then /auth/otp/verify) using any identifier above.');
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });